-- Module access rules have a polymorphic scope (SEC-06-003): each rule follows its scope target; GLOBAL rules are read-only to colleges.
ALTER TABLE "module_access_rules" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE "module_access_rules" FORCE ROW LEVEL SECURITY;
--> statement-breakpoint
DROP POLICY IF EXISTS tenant_isolation_scope ON "module_access_rules";
--> statement-breakpoint
CREATE POLICY tenant_isolation_scope ON "module_access_rules" USING (app_rls_bypass() OR "scope_type" = 'GLOBAL' OR ("scope_type" = 'COLLEGE' AND "scope_id" = nullif(current_setting('app.college_id', true), '')::uuid) OR ("scope_type" = 'ORGANIZATION' AND EXISTS (SELECT 1 FROM "organizations" AS p WHERE p."id" = "module_access_rules"."scope_id")) OR ("scope_type" = 'MEMBERSHIP' AND EXISTS (SELECT 1 FROM "college_memberships" AS p WHERE p."id" = "module_access_rules"."scope_id")) OR ("scope_type" = 'SECTION' AND EXISTS (SELECT 1 FROM "sections" AS p WHERE p."id" = "module_access_rules"."scope_id")) OR ("scope_type" = 'COHORT' AND EXISTS (SELECT 1 FROM "cohorts" AS p WHERE p."id" = "module_access_rules"."scope_id")) OR ("scope_type" = 'PROGRAM' AND EXISTS (SELECT 1 FROM "programs" AS p WHERE p."id" = "module_access_rules"."scope_id")) OR ("scope_type" = 'DEPARTMENT' AND EXISTS (SELECT 1 FROM "departments" AS p WHERE p."id" = "module_access_rules"."scope_id"))) WITH CHECK (app_rls_bypass() OR ("scope_type" = 'COLLEGE' AND "scope_id" = nullif(current_setting('app.college_id', true), '')::uuid) OR ("scope_type" = 'ORGANIZATION' AND EXISTS (SELECT 1 FROM "organizations" AS p WHERE p."id" = "module_access_rules"."scope_id")) OR ("scope_type" = 'MEMBERSHIP' AND EXISTS (SELECT 1 FROM "college_memberships" AS p WHERE p."id" = "module_access_rules"."scope_id")) OR ("scope_type" = 'SECTION' AND EXISTS (SELECT 1 FROM "sections" AS p WHERE p."id" = "module_access_rules"."scope_id")) OR ("scope_type" = 'COHORT' AND EXISTS (SELECT 1 FROM "cohorts" AS p WHERE p."id" = "module_access_rules"."scope_id")) OR ("scope_type" = 'PROGRAM' AND EXISTS (SELECT 1 FROM "programs" AS p WHERE p."id" = "module_access_rules"."scope_id")) OR ("scope_type" = 'DEPARTMENT' AND EXISTS (SELECT 1 FROM "departments" AS p WHERE p."id" = "module_access_rules"."scope_id")));
